window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b9b61510c68e800d"]={"versions": [{"id": "FIG-b9b61510c68e800d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Transformations- und Architekturdiagramm im Kontext des AUTOSAR-Transformationsprozesses von Software-Komponentenstrukturen (SWC) hin zu verhaltensbasierten Modellierungs- und Simulationsumgebungen (Behavioral Modeling Tools, BMT gemäß AUTOSAR TR Interaction with Behavioral Models). Das Diagramm veranschaulicht das strukturerhaltende Mapping einer hierarchischen AUTOSAR-Kompositionsstruktur auf eine korrespondierende Rahmenstruktur (Model Frames) in Modellierungswerkzeugen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei hierarchische Baumstrukturen, verbunden durch einen breiten Transformationspfeil:</p>\n<ul class=\"fig-list\"><li><strong>Hierarchical SW-C Structure (Links, Quellmodell):</strong>\n<ul class=\"fig-list\"><li>Oberste Ebene: <code>SW-C i</code> (als <code>Composition</code> klassifiziert).\n</li><li>Mittlere Ebene: Unterkomponenten von <code>SW-C i</code>, bestehend aus <code>SW-C j</code> (als <code>Atomic software component</code> klassifiziert) und <code>SW-C k</code> (als geschachtelte <code>Composition</code> klassifiziert).\n</li><li>Untere Ebene: Unterkomponenten von <code>SW-C k</code>, bestehend aus <code>SW-C l</code> und <code>SW-C m</code> (jeweils als <code>Atomic software component</code> klassifiziert).\n</li><li>Grafische Darstellung der SW-Cs erfolgt in einfachen Rechtecken mit dünner Konturlinie.\n</li></ul>\n</li><li><strong>Hierarchical Model Frame Structure (Rechts, Zielmodell):</strong>\n<ul class=\"fig-list\"><li>Oberste Ebene: <code>Model Frame i</code>.\n</li><li>Mittlere Ebene: Untergeordnete Rahmen <code>Model Frame j</code> und <code>Model Frame k</code>.\n</li><li>Untere Ebene: Untergeordnete Rahmen von <code>Model Frame k</code>, bestehend aus <code>Model Frame l</code> und <code>Model Frame n</code> (Typo/Diskrepanz im Bezeichner <code>n</code> korrespondierend zu <code>SW-C m</code>).\n</li><li>Grafische Darstellung der Model Frames erfolgt in Rechtecken mit fett hervorgehobener Konturlinie.\n</li></ul>\n</li><li>Schnittstellenverbindungen (Ports, Connectors) sind abstrahiert und nicht explizit dargestellt; die Kanten repräsentieren reine Dekompositions- bzw. Enthaltenseins-Relationen (CompositionType -&gt; ComponentPrototype).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische 1:1-Strukturtransformation (Modell-zu-Modell-Transformation bzw. Konvertierung). Ein Konverter liest die hierarchische Dekomposition der AUTOSAR-Softwarearchitektur ein und erzeugt eine strukturgleiche Schachtelungstiefe und -topologie im Zielwerkzeug: Jede <code>Composition</code> wird auf einen kapselnden Modellrahmen abgebildet, und jede atomare Softwarekomponente (<code>Atomic software component</code>) wird als elementarer Modellrahmen abgebildet, der die Aufnahme des eigentlichen internen Verhaltensmodells (InternalBehavior / BMT-Subsystem) vorbereitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe gemäß <code>[TR_ATBM_00004]</code>: Ein Modellkonverter muss beim Export in ein Verhaltensmodellwerkzeug die vollständige Hierarchie von <code>CompositionType</code> und den darin enthaltenen <code>ComponentPrototypes</code> konservieren. Ein Abflachen (Flattening) der Hierarchie ist für diesen Anwendungsfall unzulässig. Entwickler von Modellierungsbrücken und Konvertern müssen sicherstellen, dass Instanziierungen und Prototypen die Design Contracts nicht verletzen und die hierarchischen Kapselungsgrenzen in Form korrespondierender Subsysteme/Frames im Zielwerkzeug exakt repliziert werden.</p>"}, {"id": "FIG-aaa0397a8cca8d50", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Transformations- und Architekturdiagramm im Kontext des AUTOSAR-Transformationsprozesses von Software-Komponentenstrukturen (SWC) hin zu verhaltensbasierten Modellierungs- und Simulationsumgebungen (Behavioral Modeling Tools, BMT gemäß AUTOSAR TR Interaction with Behavioral Models). Das Diagramm veranschaulicht das strukturerhaltende Mapping einer hierarchischen AUTOSAR-Kompositionsstruktur auf eine korrespondierende Rahmenstruktur (Model Frames) in Modellierungswerkzeugen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei hierarchische Baumstrukturen, verbunden durch einen breiten Transformationspfeil:</p>\n<ul class=\"fig-list\"><li><strong>Hierarchical SW-C Structure (Links, Quellmodell):</strong>\n<ul class=\"fig-list\"><li>Oberste Ebene: <code>SW-C i</code> (als <code>Composition</code> klassifiziert).\n</li><li>Mittlere Ebene: Unterkomponenten von <code>SW-C i</code>, bestehend aus <code>SW-C j</code> (als <code>Atomic software component</code> klassifiziert) und <code>SW-C k</code> (als geschachtelte <code>Composition</code> klassifiziert).\n</li><li>Untere Ebene: Unterkomponenten von <code>SW-C k</code>, bestehend aus <code>SW-C l</code> und <code>SW-C m</code> (jeweils als <code>Atomic software component</code> klassifiziert).\n</li><li>Grafische Darstellung der SW-Cs erfolgt in einfachen Rechtecken mit dünner Konturlinie.\n</li></ul>\n</li><li><strong>Hierarchical Model Frame Structure (Rechts, Zielmodell):</strong>\n<ul class=\"fig-list\"><li>Oberste Ebene: <code>Model Frame i</code>.\n</li><li>Mittlere Ebene: Untergeordnete Rahmen <code>Model Frame j</code> und <code>Model Frame k</code>.\n</li><li>Untere Ebene: Untergeordnete Rahmen von <code>Model Frame k</code>, bestehend aus <code>Model Frame l</code> und <code>Model Frame n</code> (Typo/Diskrepanz im Bezeichner <code>n</code> korrespondierend zu <code>SW-C m</code>).\n</li><li>Grafische Darstellung der Model Frames erfolgt in Rechtecken mit fett hervorgehobener Konturlinie.\n</li></ul>\n</li><li>Schnittstellenverbindungen (Ports, Connectors) sind abstrahiert und nicht explizit dargestellt; die Kanten repräsentieren reine Dekompositions- bzw. Enthaltenseins-Relationen (CompositionType -&gt; ComponentPrototype).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische 1:1-Strukturtransformation (Modell-zu-Modell-Transformation bzw. Konvertierung). Ein Konverter liest die hierarchische Dekomposition der AUTOSAR-Softwarearchitektur ein und erzeugt eine strukturgleiche Schachtelungstiefe und -topologie im Zielwerkzeug: Jede <code>Composition</code> wird auf einen kapselnden Modellrahmen abgebildet, und jede atomare Softwarekomponente (<code>Atomic software component</code>) wird als elementarer Modellrahmen abgebildet, der die Aufnahme des eigentlichen internen Verhaltensmodells (InternalBehavior / BMT-Subsystem) vorbereitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe gemäß <code>[TR_ATBM_00004]</code>: Ein Modellkonverter muss beim Export in ein Verhaltensmodellwerkzeug die vollständige Hierarchie von <code>CompositionType</code> und den darin enthaltenen <code>ComponentPrototypes</code> konservieren. Ein Abflachen (Flattening) der Hierarchie ist für diesen Anwendungsfall unzulässig. Entwickler von Modellierungsbrücken und Konvertern müssen sicherstellen, dass Instanziierungen und Prototypen die Design Contracts nicht verletzen und die hierarchischen Kapselungsgrenzen in Form korrespondierender Subsysteme/Frames im Zielwerkzeug exakt repliziert werden.</p>"}], "trans": [{"from": "FIG-b9b61510c68e800d", "to": "FIG-aaa0397a8cca8d50", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
